--
-- Table structure for table `cat_profile`
--

DROP TABLE IF EXISTS `cat_profile`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `cat_profile` (
  `cat_id` bigint NOT NULL AUTO_INCREMENT COMMENT '猫咪id',
  `archive_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '档案编号（唯一）',
  `cat_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '猫咪名字',
  `alias` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '别名',
  `breed` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '品种',
  `sex` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '2' COMMENT '性别（0公 1母 2未知）',
  `age_estimate` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '大概年龄（估算）',
  `weight` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '体重',
  `personality` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '性格',
  `source` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '1' COMMENT '来源（1抓捕/TNR 2救助捡到 3他人移交 4其他）',
  `capture_date` date DEFAULT NULL COMMENT '抓捕/救助日期',
  `capture_point` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '抓捕点位（投喂点地址）',
  `neutered` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '0' COMMENT '是否绝育（0未绝育 1已绝育 2未知）',
  `dewormed` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '0' COMMENT '是否驱虫（0未驱虫 1已驱虫）',
  `vaccinated` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '0' COMMENT '是否疫苗（0未疫苗 1已疫苗）',
  `feature` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '标志性特征（伤疤缺耳断尾异色眼等）',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '1' COMMENT '猫咪状态（1在养 2基地内治疗中 3外送医院治疗中 4已放归 5已领养 6已离世 7TNR治疗中 8姑息照料）',
  `base_id` bigint DEFAULT NULL COMMENT '当前所在基地id',
  `ward_id` bigint DEFAULT NULL COMMENT '当前所在病房id',
  `owner_base_id` bigint DEFAULT NULL COMMENT '归属基地id',
  `hospital_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '外送医院名称（状态为外送时）',
  `qr_code` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '二维码图片地址（Base64）',
  `archived` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '0' COMMENT '是否归档（0未归档 1已归档）',
  `remark` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注（应激程度、是否怕人、特殊习性）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '0' COMMENT '删除标志（0存在 2删除）',
  PRIMARY KEY (`cat_id`),
  UNIQUE KEY `uk_archive_no` (`archive_no`),
  KEY `idx_status` (`status`),
  KEY `idx_base` (`base_id`),
  KEY `idx_owner_base` (`owner_base_id`)
) ENGINE=InnoDB AUTO_INCREMENT=124 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='猫咪档案表';
/*!40101 SET character_set_client = @saved_cs_client */;

