INSERT INTO `sys_notice` VALUES (1,'流浪猫救助管理系统正式启用','1',_binary '各位同事：\n\n流浪猫救助管理系统即日起正式启用，档案登记、疫苗驱虫、诊疗用药、外送转诊、领养回访、物资库存等业务统一在本系统办理。\n\n原纸质台账请于本周内完成补录，之后不再并行维护。','0','admin','2026-10-27 11:40:16','',NULL,'管理员'),(2,'业务数据录入规范','2',_binary '为保证台账可追溯，请遵守以下录入要求：\n\n一、猫咪入站当天完成档案登记，同步录入毛色、品种、入站来源。\n二、疫苗、驱虫当天接种当天登记，下次到期日必须填写。\n三、领养回访按 3 天、1 个月、3 个月三个节点安排计划。\n四、物资出入库当日登记，库存低于预警值会生成提醒。','0','admin','2026-10-27 11:40:16','',NULL,'管理员');
/*!40000 ALTER TABLE `sys_notice` ENABLE KEYS */;
UNLOCK TABLES;

