INSERT INTO `sys_role` VALUES (1,'超级管理员','admin',1,'1',1,1,'0','0','admin','2026-10-27 11:40:17','',NULL,'系统内置角色，拥有全部权限；不参与业务分配，不在角色列表中显示'),(2,'医生','doctor',3,'2',1,1,'0','0','admin','2026-10-27 11:40:17','admin','2026-10-27 12:24:38','医疗相关权限；不可改系统设置、不可删档案、物资只能查看、财务只能查看账单'),(3,'助理','assistant',4,'2',1,1,'0','0','admin','2026-10-27 11:40:17','admin','2026-10-27 13:32:10','基础信息录入、用药打卡、拍照上传、档案新建、物资出入登记、回访录入；不可改历史诊断、不可删档案、不可管理账号与标签库'),(4,'管理员','manager',2,'1',1,1,'0','0','admin','2026-10-27 11:40:17','admin','2026-10-27 12:24:32','救助站业务管理员，管理全站业务与基础数据');
